python3 - <<'PY'
import json,csv
svcs=json.load(open('/workspace/migration/services.json'))
assert len(svcs)>=6, svcs
names={s['name'] for s in svcs}
assert len(names)==len(svcs), 'duplicate service names'
for s in svcs:
    assert s['phase'] in (1,2,3), s
phase_by_name={s['name']:s['phase'] for s in svcs}
for s in svcs:
    for dep in s.get('dependencies',[]):
        assert dep in phase_by_name, dep
        assert phase_by_name[dep]<=s['phase'], (s,dep)
risks=list(csv.DictReader(open('/workspace/migration/risks.csv')))
assert len(risks)>=6, risks
for r in risks:
    for k in ('id','description','likelihood','impact','mitigation','owner'):
        assert r[k].strip(), (r,k)
PY
